import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.es-12sf8.js";var i=JSON.parse(`{"title":"Smart Merge Module","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/modules/smart-merge.md","filePath":"en/deep-dive/modules/smart-merge.md","lastUpdated":1787979384000}`),a={name:`deep-dive/modules/smart-merge.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="smart-merge-module" tabindex="-1">Smart Merge Module <a class="header-anchor" href="#smart-merge-module" aria-label="Permalink to “Smart Merge Module”">​</a></h1><p>Smart Merge is an optional text conflict resolver for Markdown files. It keeps a base snapshot for each mergeable file, then uses that snapshot to distinguish independent edits from conflicting edits. The module registers a remote file system wrapper, the <code>smartMerge</code> conflict resolver, and settings.</p><h2 id="supported-files-and-registration" tabindex="-1">Supported Files and Registration <a class="header-anchor" href="#supported-files-and-registration" aria-label="Permalink to “Supported Files and Registration”">​</a></h2><p>Only paths that end in <code>.md</code> or <code>.markdown</code> after trimming and lowercasing are mergeable. Other files are passed through without base-text tracking.</p><p>The module wraps the remote file system with priority <code>20_098</code>. The wrapper delegates normal file system behavior to the wrapped instance and adds base snapshot maintenance. The resolver is registered under the ID <code>smartMerge</code>.</p><h2 id="base-snapshot-lifecycle" tabindex="-1">Base Snapshot Lifecycle <a class="header-anchor" href="#base-snapshot-lifecycle" aria-label="Permalink to “Base Snapshot Lifecycle”">​</a></h2><p>The wrapper receives a <code>uni-kv</code> <code>StoreAsync&lt;string&gt;</code> for its local/remote file-system namespace. The store maps file keys to plain text snapshots.</p><ul><li>After a successful <code>write()</code>, the wrapper stores the written value as text if the path is mergeable. A failed write does not update the snapshot.</li><li>After a successful <code>move()</code>, an existing snapshot moves from the old key to the new key. A move to the same key does not change the store.</li><li>After a successful <code>delete()</code>, the snapshot for that key is deleted.</li><li><code>read()</code>, <code>readStream()</code>, <code>mkdir()</code>, <code>stat()</code>, <code>exists()</code>, and <code>list()</code> keep their original behavior.</li></ul><p>The database store name is <code>base-text-&lt;namespace&gt;</code>, where the namespace is the same namespace selected by plugin core for the local and remote file systems. This prevents snapshots from being shared between unrelated sync targets.</p><h2 id="conflict-resolution-flow" tabindex="-1">Conflict Resolution Flow <a class="header-anchor" href="#conflict-resolution-flow" aria-label="Permalink to “Conflict Resolution Flow”">​</a></h2><p>The resolver receives both <code>FileStat</code> values, the file key, both file systems, and the sync record store. It reads local content, remote content, and the stored base snapshot concurrently.</p><p>When a base snapshot exists:</p><ol><li>Decode local and remote content as text.</li><li>If both texts are identical, do not write either side; only refresh the sync record with the existing UIDs.</li><li>Otherwise, merge the three texts with local as <code>a</code>, remote as <code>b</code>, and the stored snapshot as <code>o</code>.</li><li>Write the merged text only to sides whose current text differs from it.</li><li>Record the resulting local and remote UIDs.</li></ol><p>When no base snapshot exists, Smart Merge cannot distinguish independent changes. It falls back to latest-survive behavior: copy the side with the newer modification time to the other side. Local wins only when <code>local.mtime &gt; remote.mtime</code>; equal timestamps select the remote side. The fallback uses the SDK transfer helper, so large content can be transferred as a stream.</p><h2 id="merge-model" tabindex="-1">Merge Model <a class="header-anchor" href="#merge-model" aria-label="Permalink to “Merge Model”">​</a></h2><p>The merge algorithm is a recursive diff3 merge. It is text-oriented rather than Markdown-AST-aware and operates at several granularities:</p><ul><li>At document level, it splits content into non-blank lines and preserves the newline runs between them.</li><li>Fenced blocks beginning with triple backticks, <code>~~~</code>, or <code>$$</code> are split as code and compared line by line. Their opening and closing fences remain part of the merged content.</li><li>Prose is split into words and punctuation while whitespace remains in the joints between tokens. For scripts commonly written without spaces, it uses <code>Intl.Segmenter</code> with locale detection for Japanese, Chinese, Thai, Lao, Khmer, Myanmar, and Tibetan text.</li></ul><p>For each diff3 region, the algorithm applies these rules:</p><ul><li>If local and remote are equal, keep that value.</li><li>If one side still equals the base, keep the change from the other side.</li><li>If both sides changed the same region differently, emit a conflict.</li><li>If a conflicting region can be split at a finer granularity, recurse before emitting markers. This allows unrelated edits within one line or code block to merge independently.</li></ul><p>Whitespace and newline joints are retained from the source spans while regions are combined. The algorithm does not attempt semantic or syntactic validation of the resulting document.</p><h2 id="conflict-markers" tabindex="-1">Conflict Markers <a class="header-anchor" href="#conflict-markers" aria-label="Permalink to “Conflict Markers”">​</a></h2><p>Conflicting content is written directly into the merged file. A normal two-sided conflict is emitted as local content wrapped by the <code>ours</code> markers, followed by remote content wrapped by the <code>theirs</code> markers. When one side deletes content and the other changes it, the surviving content is wrapped by deletion markers.</p><p>The default markers are:</p><table tabindex="0"><thead><tr><th>Purpose</th><th>Start</th><th>End</th></tr></thead><tbody><tr><td>Local (<code>ours</code>)</td><td><code>&lt;mark class=&quot;conflict ours&quot;&gt;</code></td><td><code>&lt;/mark&gt;</code></td></tr><tr><td>Remote (<code>theirs</code>)</td><td><code>&lt;mark class=&quot;conflict theirs&quot;&gt;</code></td><td><code>&lt;/mark&gt;</code></td></tr><tr><td>Deletion</td><td><code>&lt;mark class=&quot;conflict deleted&quot;&gt;</code></td><td><code>&lt;/mark&gt;</code></td></tr></tbody></table><p>Users can configure all six marker strings independently in the Smart Merge settings. Changes update module settings and are persisted through the plugin settings store.</p>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};